const platform = 'bilibili';
const accountId = 10;
const inputVideo = String(tobub.params.video || '').trim();
const requestedCount = Number(tobub.params.maxComments ?? 50);
const maxScrolls = Number(tobub.params.maxScrolls ?? 18);
const collectedAt = new Date().toISOString();
let accountKey = '';
let bvid = '';
let sourceUrl = '';
let pageTitle = '';
let page = null;
let scrollCount = 0;
let invalidRecordCount = 0;
let duplicateCount = 0;
let failureCount = 0;
let persistedCount = 0;
let databaseReadbackCount = 0;
let videoAnchorVerified = false;
let challengeDetected = false;
let verificationEncountered = false;
let verificationWaitSeconds = 0;
const errorSample = [];
const commentsById = new Map();
const scope = '一级评论';
let sort = 'unknown';
const pageScanExpression = "() => {\n  const bodyText = document.body?.innerText || '';\n  const challengeDetected = /请在下图依次点击|安全验证|验证码|人机验证|访问异常/.test(bodyText);\n  const host = document.querySelector('bili-comments');\n  const root = host?.shadowRoot;\n  const header = root?.querySelector('bili-comments-header-renderer')?.shadowRoot;\n  const feed = root?.querySelector('#feed');\n  const threads = Array.from(feed?.querySelectorAll('bili-comment-thread-renderer') || []);\n  const comments = threads.map((thread, index) => {\n    const data = thread.data || {};\n    const commentRoot = thread.shadowRoot?.querySelector('bili-comment-renderer')?.shadowRoot;\n    const actionRoot = commentRoot?.querySelector('bili-comment-action-buttons-renderer')?.shadowRoot;\n    const userRoot = commentRoot?.querySelector('bili-comment-user-info')?.shadowRoot;\n    const richRoot = commentRoot?.querySelector('bili-rich-text')?.shadowRoot;\n    const message = typeof data.content?.message === 'string'\n      ? data.content.message\n      : String(richRoot?.querySelector('#contents')?.textContent || '');\n    const ctime = Number(data.ctime);\n    const rawLike = Number(data.like);\n    const rawReplyCount = Number(data.rcount);\n    let createdAt = '';\n    if (Number.isFinite(ctime) && ctime > 0) {\n      try { createdAt = new Date(ctime * 1000).toISOString(); } catch {}\n    }\n    const rootValue = data.root ?? data.root_str;\n    if (rootValue !== undefined && rootValue !== null && Number(rootValue) !== 0) return null;\n    return {\n      rpid: String(data.rpid_str || data.rpid || thread.commonTrackData?.rpid || ''),\n      text: String(message || '').replace(/\\r\\n?/g, '\\n').trim().slice(0, 5000),\n      author: String(userRoot?.querySelector('#user-name a')?.textContent || data.member?.uname || '').trim().slice(0, 160),\n      authorId: String(commentRoot?.querySelector('#user-avatar')?.getAttribute('data-user-profile-id') || data.mid_str || data.mid || ''),\n      likeCount: Number.isFinite(rawLike) && rawLike >= 0 ? rawLike : Number(actionRoot?.querySelector('#like #count')?.textContent || 0),\n      replyCount: Number.isFinite(rawReplyCount) && rawReplyCount >= 0 ? rawReplyCount : 0,\n      createdAt,\n      displayedTime: String(actionRoot?.querySelector('#pubdate')?.textContent || '').trim().slice(0, 80),\n      isPinned: Boolean(commentRoot?.querySelector('#top')),\n      position: index + 1,\n      textTruncated: String(message || '').length > 5000\n    };\n  }).filter(Boolean);\n  const countText = String(header?.querySelector('#count')?.textContent || '').replace(/\\s+/g, ' ').trim();\n  const sortClass = String(header?.querySelector('#sort-actions')?.className || '').trim();\n  const title = String(document.title || '').replace(/_哔哩哔哩_bilibili\\s*$/, '').trim();\n  return {\n    title,\n    pageUrl: location.href,\n    challengeDetected,\n    moduleFound: Boolean(host && root && header),\n    threadCount: threads.length,\n    comments,\n    reportedTotalCountText: countText,\n    sortClass,\n    sort: /\\bhot\\b/i.test(sortClass) ? 'hot' : 'unknown'\n  };\n}";

const emptyResult = (status, message, extra = {}) => ({
  status,
  sourceUrl,
  videoBvid: bvid,
  pageTitle,
  collectedAt,
  accountKey,
  scope,
  sort,
  requestedCount: Number.isInteger(requestedCount) ? requestedCount : 0,
  reportedTotalCount: -1,
  reportedTotalCountText: '',
  visibleThreadCount: 0,
  extractedCount: 0,
  persistedCount: 0,
  databaseReadbackCount: 0,
  videoAnchorVerified: false,
  invalidRecordCount: 0,
  duplicateCount: 0,
  failureCount: 0,
  scrollCount,
  challengeDetected,
  verificationEncountered,
  verificationWaitSeconds,
  reachedLimit: false,
  message,
  errorSample: [],
  records: [],
  ...extra
});

if (!Number.isInteger(requestedCount) || requestedCount < 1 || requestedCount > 200) {
  return emptyResult('blocked', 'maxComments 必须是 1–200 的整数；未访问页面或写入数据库。');
}
if (!Number.isInteger(maxScrolls) || maxScrolls < 4 || maxScrolls > 30) {
  return emptyResult('blocked', 'maxScrolls 必须是 4–30 的整数；未访问页面或写入数据库。');
}
const directMatch = inputVideo.match(/^(BV[a-zA-Z0-9]{10})$/);
const urlMatch = inputVideo.match(/^https?:\/\/(?:www\.|m\.)?bilibili\.com\/video\/(BV[a-zA-Z0-9]{10})(?:[/?#]|$)/i);
bvid = directMatch?.[1] || urlMatch?.[1] || '';
if (!bvid) {
  return emptyResult('blocked', '请传入 BVID（BV 加 10 位字符）或 bilibili.com/video/BV… 官方视频链接。未访问页面或写入数据库。');
}
sourceUrl = 'https://www.bilibili.com/video/' + bvid;

let biliAccount;
try {
  biliAccount = await tobub.db.getAccountById(accountId);
} catch {
  return emptyResult('blocked', '无法读取 Tobub bili 账号配置；请检查已登录 Profile。未访问页面或写入数据库。');
}
accountKey = String(biliAccount?.account_key || '');
if (accountKey !== 'bili' || Number(biliAccount?.is_active) !== 1) {
  return emptyResult('blocked', 'Tobub 的 bili 账号配置不匹配或已停用。请在运行设置中选择有效的 bili 账号/Profile。未访问页面或写入数据库。');
}

try {
  await tobub.atoms.navigate({ url: sourceUrl, waitUntil: 'domcontentloaded' });
} catch {
  return emptyResult('blocked', '打开 Bilibili 视频失败；未写入数据库。');
}

const readPage = async () => {
  const result = await tobub.atoms.evaluate({ mode: 'function', expression: pageScanExpression });
  return result?.value ?? result;
};
const waitStartedAt = Date.now();
const waitDeadline = waitStartedAt + 90000;
let consecutiveReadFailures = 0;
while (Date.now() < waitDeadline) {
  try {
    page = await readPage();
    consecutiveReadFailures = 0;
  } catch {
    consecutiveReadFailures++;
    if (consecutiveReadFailures >= 3) {
      return emptyResult('blocked', '无法读取视频评论页面；未写入数据库。页面结构或浏览器状态可能已变化。');
    }
  }
  if (page?.challengeDetected) {
    challengeDetected = true;
    verificationEncountered = true;
    await tobub.atoms.waitFor({ delay: 1500 });
    continue;
  }
  if (page?.pageUrl && !/^https:\/\/(?:www\.)?bilibili\.com\/video\//i.test(page.pageUrl)) {
    return emptyResult('blocked', '页面跳转到非 Bilibili 视频地址，已停止采集且未写入数据库。');
  }
  if (page?.moduleFound && (page.threadCount > 0 || page.reportedTotalCountText === '0')) break;
  if (scrollCount < maxScrolls) {
    await tobub.atoms.scroll({ direction: 'down', distance: 1200 });
    scrollCount++;
  }
  await tobub.atoms.waitFor({ delay: 1000 });
}
verificationWaitSeconds = Math.round((Date.now() - waitStartedAt) / 1000);
if (page?.challengeDetected) {
  challengeDetected = true;
  return emptyResult('blocked', '检测到 Bilibili 安全验证，当前运行已等待 90 秒仍未完成；请在可见浏览器中人工完成验证后重新运行，本次未写入数据库。');
}
if (!page?.moduleFound || (page.threadCount < 1 && page.reportedTotalCountText !== '0')) {
  return emptyResult('blocked', '在 90 秒及滚动上限内未加载到评论区；未写入数据库。请确认视频可访问或页面结构未变化。');
}
pageTitle = String(page.title || '').slice(0, 300);
sort = page?.sort === 'hot' ? 'hot' : 'unknown';
const reportedTotalCount = /^\d+$/.test(String(page.reportedTotalCountText || '').trim())
  ? Number(page.reportedTotalCountText.trim())
  : -1;
if (reportedTotalCount === 0 && page.threadCount === 0) {
  return emptyResult('complete', 'Bilibili 页面显示该视频当前没有一级评论。', {
    pageTitle, reportedTotalCount, reportedTotalCountText: String(page.reportedTotalCountText || ''),
    visibleThreadCount: 0, verificationWaitSeconds
  });
}

const absorbComments = rows => {
  for (const item of rows || []) {
    const id = String(item?.rpid || '').trim();
    const text = String(item?.text || '').trim();
    if (!id || !/^\d{1,24}$/.test(id) || !text) {
      invalidRecordCount++;
      continue;
    }
    if (commentsById.has(id)) {
      duplicateCount++;
      continue;
    }
    if (commentsById.size < requestedCount) {
      commentsById.set(id, {
        rpid: id,
        videoBvid: bvid,
        text: text.slice(0, 5000),
        author: String(item.author || '').slice(0, 160),
        authorId: String(item.authorId || '').slice(0, 40),
        likeCount: Number.isFinite(Number(item.likeCount)) ? Math.max(0, Number(item.likeCount)) : 0,
        replyCount: Number.isFinite(Number(item.replyCount)) ? Math.max(0, Number(item.replyCount)) : 0,
        createdAt: String(item.createdAt || ''),
        displayedTime: String(item.displayedTime || '').slice(0, 80),
        isPinned: Boolean(item.isPinned),
        position: Number(item.position) || commentsById.size + 1,
        textTruncated: Boolean(item.textTruncated),
        videoUrl: sourceUrl,
        persisted: false
      });
    }
  }
};
absorbComments(page.comments);

let stableScrolls = 0;
let scanFailures = 0;
while (commentsById.size < requestedCount && scrollCount < maxScrolls && stableScrolls < 3) {
  const previousCount = commentsById.size;
  await tobub.atoms.scroll({ direction: 'down', distance: 1200 });
  scrollCount++;
  await tobub.atoms.waitFor({ delay: 900 });
  try {
    page = await readPage();
    scanFailures = 0;
  } catch {
    scanFailures++;
    failureCount++;
    if (scanFailures >= 3) {
      errorSample.push('连续三次读取评论卡片失败');
      break;
    }
    continue;
  }
  if (page?.challengeDetected) {
    challengeDetected = true;
    verificationEncountered = true;
    return emptyResult('blocked', '采集过程中出现 Bilibili 安全验证；为避免保存不完整数据，本次未写入数据库。请在可见浏览器中人工完成后重试。', {
      pageTitle: String(page.title || pageTitle).slice(0, 300),
      reportedTotalCount, reportedTotalCountText: String(page.reportedTotalCountText || ''),
      visibleThreadCount: Number(page.threadCount) || 0, invalidRecordCount, duplicateCount,
      failureCount, scrollCount, verificationWaitSeconds
    });
  }
  absorbComments(page?.comments);
  if (commentsById.size === previousCount) stableScrolls++;
  else stableScrolls = 0;
}
pageTitle = String(page?.title || pageTitle).slice(0, 300);
sort = page?.sort === 'hot' ? 'hot' : 'unknown';
const visibleThreadCount = Number(page?.threadCount) || 0;
const reportedTotalCountText = String(page?.reportedTotalCountText || '');
const finalRecords = Array.from(commentsById.values()).slice(0, requestedCount);
if (!finalRecords.length) {
  return emptyResult('blocked', '评论区已加载但未提取到带有有效 rpid 和正文的一级评论；未写入数据库。', {
    pageTitle, reportedTotalCount, reportedTotalCountText, visibleThreadCount,
    invalidRecordCount, duplicateCount, failureCount, scrollCount, verificationWaitSeconds
  });
}

let videoItem;
try {
  const parentSaved = await tobub.db.saveContent({
    platform,
    contentType: 'video',
    externalId: bvid,
    title: pageTitle || bvid,
    summary: 'Bilibili 视频评论采集关联视频',
    url: sourceUrl,
    metadata: { source: 'single_video_comments', videoBvid: bvid, collectedAt },
    rawData: { videoBvid: bvid, title: pageTitle, url: sourceUrl, collectedAt },
    tags: ['Bilibili', '视频评论'],
    observationSource: 'bilibili_single_video_comments',
    observationMeta: { sourceUrl, videoBvid: bvid, collectedAt, role: 'parent-video' },
    displayPath: '视频评论/' + bvid,
    sortOrder: 0
  });
  if (!parentSaved?.contentItemId || !parentSaved?.observationId) throw new Error('视频锚点保存失败');
  videoItem = await tobub.db.getContentItemByExternalId(platform, 'video', bvid);
  videoAnchorVerified = videoItem?.platform === platform && videoItem?.content_type === 'video' && String(videoItem?.external_id) === bvid;
  if (!videoAnchorVerified) throw new Error('视频锚点回读失败');
} catch (error) {
  failureCount++;
  errorSample.push(String(error?.message || '视频锚点写入/回读失败').slice(0, 180));
  return emptyResult('blocked', '评论数据已提取，但视频关联锚点写入或回读未通过；未写入评论记录。', {
    pageTitle, reportedTotalCount, reportedTotalCountText, visibleThreadCount,
    extractedCount: finalRecords.length, videoAnchorVerified, invalidRecordCount,
    duplicateCount, failureCount, scrollCount, verificationWaitSeconds,
    errorSample
  });
}

const parentId = Number(videoItem.id);
for (let i = 0; i < finalRecords.length; i++) {
  const item = finalRecords[i];
  const storedTitle = item.text.slice(0, 500);
  try {
    const saved = await tobub.db.saveContent({
      platform,
      contentType: 'comment',
      externalId: item.rpid,
      parentId,
      title: storedTitle,
      summary: item.author,
      url: sourceUrl,
      metadata: {
        source: 'bilibili_single_video_comments',
        videoBvid: bvid,
        rpid: item.rpid,
        author: item.author,
        authorId: item.authorId,
        likeCount: item.likeCount,
        replyCount: item.replyCount,
        createdAt: item.createdAt,
        displayedTime: item.displayedTime,
        isPinned: item.isPinned,
        sort,
        position: i + 1,
        textTruncated: item.textTruncated,
        collectedAt
      },
      rawData: { ...item, sort, collectedAt },
      tags: ['Bilibili', '视频评论', '一级评论', sort === 'hot' ? '热度排序' : '排序未知'],
      observationSource: 'bilibili_single_video_comments',
      observationMeta: { sourceUrl, videoBvid: bvid, rpid: item.rpid, sort, position: i + 1, collectedAt },
      displayPath: '视频评论/' + bvid + '/' + sort + '/' + (i + 1),
      sortOrder: i + 1
    });
    if (!saved?.contentItemId || !saved?.observationId) throw new Error('数据库未返回内容记录 ID');
    persistedCount++;
    const stored = await tobub.db.getContentItemByExternalId(platform, 'comment', item.rpid);
    if (stored?.platform === platform &&
        stored?.content_type === 'comment' &&
        String(stored?.external_id) === item.rpid &&
        Number(stored?.parent_id) === parentId &&
        stored?.title === storedTitle) {
      item.persisted = true;
      databaseReadbackCount++;
    } else {
      failureCount++;
      errorSample.push('评论 ' + item.rpid + ' 的数据库回读内容或视频关联不匹配');
    }
  } catch (error) {
    failureCount++;
    errorSample.push('评论 ' + item.rpid + ': ' + String(error?.message || '写入/回读失败').slice(0, 140));
  }
}
const reachedLimit = finalRecords.length >= requestedCount;
const allVerified = videoAnchorVerified &&
  persistedCount === finalRecords.length &&
  databaseReadbackCount === finalRecords.length &&
  failureCount === 0;
const status = reachedLimit && allVerified ? 'complete' : 'partial';
return {
  status,
  sourceUrl,
  videoBvid: bvid,
  pageTitle,
  collectedAt,
  accountKey,
  scope,
  sort,
  requestedCount,
  reportedTotalCount,
  reportedTotalCountText,
  visibleThreadCount,
  extractedCount: finalRecords.length,
  persistedCount,
  databaseReadbackCount,
  videoAnchorVerified,
  invalidRecordCount,
  duplicateCount,
  failureCount,
  scrollCount,
  challengeDetected,
  verificationEncountered,
  verificationWaitSeconds,
  reachedLimit,
  message: status === 'complete'
    ? '已从可见评论区按热度顺序采集 ' + finalRecords.length + ' 条一级评论，并逐条写入数据库、回读核验及关联视频。'
    : '采集未达到完整条件：请求 ' + requestedCount + ' 条，提取 ' + finalRecords.length + ' 条，数据库确认 ' + databaseReadbackCount + ' 条；请结合滚动上限、页面总数和错误样本检查。',
  errorSample: errorSample.slice(0, 5),
  records: finalRecords
};
